window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["distillation"]={"title":"知识蒸馏：让小学生逼近教师的条件分布与行为","subtitle":"从软标签、温度与 KL，到 token/序列/特征蒸馏、覆盖缺口、容量上限和偏差继承。","thesis":"蒸馏用教师分布、表示或生成示范监督学生，使较小模型在目标数据上逼近教师。它不是把知识文件复制进小模型，而是在<b>学生容量、蒸馏数据和目标函数</b>限定下选择性保留行为，并可能继承教师错误与偏差。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"教师 logits [4,2,0]","rule":"e^(z/2) / Σ","steps":"refund .665","interpretation":"温度 2 保持排序，却让 ask/reject 的相对信息更可见"}}],"formulas":[{"id":"distillation-soft-target-loss","section":2,"formulaIndex":1,"symbols":[{"name":"p","meaning":"温度调整后分给某个类别的概率","evidence":"变成总和为 1 的概率 pᵀᵢ"},{"name":"i","meaning":"正在查看的候选类别编号","evidence":"i 是类别编号"},{"name":"T","meaning":"控制教师和学生软分布平坦程度的温度","evidence":"T 是温度"},{"name":"softmax","meaning":"把一组原始分数归一化为总和为一的概率","evidence":"softmax 把 z/T 变成总和为 1 的概率"},{"name":"z","meaning":"模型为各候选类别产生的未归一化原始分数","evidence":"z 是各类别未经归一化的原始分数"},{"name":"L","meaning":"学生在硬标签与教师信号上的综合训练损失","evidence":"L 是学生的总训练损失"},{"name":"α","meaning":"在人工真值监督和教师监督之间分配权重的系数","evidence":"α 在 0 到 1 之间"},{"name":"硬标签","meaning":"由人工或可靠规则提供的目标类别监督","evidence":"L硬标签 衡量学生与人工真值的差距"},{"name":"KL","meaning":"衡量学生软分布偏离教师软分布程度的非对称散度","evidence":"KL(p教师∥p学生) 衡量学生软分布偏离教师软分布多少"},{"name":"教师","meaning":"为蒸馏样本提供目标软分布的较强模型","evidence":"教师软分布"},{"name":"学生","meaning":"正在通过蒸馏损失更新的较小模型","evidence":"学生软分布"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"知识蒸馏由教师为较小学生产生软分布、表示或示范等训练信号。","evidence":"用一个较强或较大的教师模型"},"problem":{"answer":"它让小模型在容量和成本更低时，尽量保留教师在目标分布上的行为。","evidence":"为较小学生模型产生训练信号"},"inputOutput":{"answer":"输入是同一样本，教师输出完整候选概率，学生输出自己的近似分布。","evidence":"教师输出 refund、ask、reject 的整张概率表"},"mechanism":{"answer":"软分布保留次优类别与边界关系，学生通过损失逼近而非只看唯一标签。","evidence":"学生拟合教师完整分布"},"interpretation":{"answer":"学生接近教师表示行为迁移成功，不等于教师判断具有事实真值。","evidence":"不表示教师判断是真值"},"boundary":{"answer":"教师概率会失准并携带偏差，必须与硬真值结合并在真实标签上校准。","evidence":"硬真值与教师信号应组合"}},{"section":2,"definition":{"answer":"温度软化先缩小 logits 差异，再用软分布 KL 与硬标签损失共同训练学生。","evidence":"增大 T 缩小 logit 差"},"problem":{"answer":"它让接近零的次优类别产生可学习信号，传递教师认为错误类别有多相似。","evidence":"能显示教师认为哪些错误“比较像”"},"inputOutput":{"answer":"输入是教师学生 logits、温度和真值，输出是软概率与综合蒸馏损失。","evidence":"L 是学生的总训练损失"},"mechanism":{"answer":"softmax 处理 z/T，损失按 alpha 混合硬标签项与经 T 平方缩放的 KL 项。","evidence":"控制真值监督与教师监督的比例"},"interpretation":{"answer":"正向 KL 更惩罚学生漏掉教师支持的类别，反向方向更倾向高概率模式。","evidence":"鼓励学生覆盖教师分布"},"boundary":{"answer":"温度只软化训练信号，不会自动修复教师或学生部署概率的校准。","evidence":"温度不是校准修复"}},{"section":3,"definition":{"answer":"数值例把同一教师 logits 分别以温度一和二归一化，比较软化效果。","evidence":"三个退款动作的温度软化"},"problem":{"answer":"它具体展示较高温度怎样在不改排序时提高次优类别的可见概率。","evidence":"在 T=1 与 T=2 时怎样变化"},"inputOutput":{"answer":"输入是三个动作的 logits 与温度，输出是各动作归一化后的概率。","evidence":"教师 logits [4,2,0]"},"mechanism":{"answer":"温度二先把 logits 除二，再取指数并除以各指数之和。","evidence":"e^(z/2) / Σ"},"interpretation":{"answer":"refund 仍最高，但 ask 与 reject 概率上升，为学生提供相对关系梯度。","evidence":"让 ask/reject 的相对信息更可见"},"boundary":{"answer":"仅硬标签只推动 refund 接近一，无法告诉学生两个错误类别的相对相似度。","evidence":"仅硬标签会只推动 refund 接近 1"}},{"section":4,"definition":{"answer":"蒸馏可在 logits、内部特征、样本关系或最终序列四类信号层级进行。","evidence":"先区分四种信号"},"problem":{"answer":"它说明教师接口受限或师生架构不同时，仍可选择哪类可见信号迁移。","evidence":"拿不到教师内部状态时"},"inputOutput":{"answer":"输入是教师接口、学生架构和目标能力，输出是对应监督数据与学生损失。","evidence":"输出是概率、特征、关系或示范数据"},"mechanism":{"answer":"学生分别匹配候选分数、中间向量、相似结构或教师生成的回答序列。","evidence":"越靠内部，提供的信息越细"},"interpretation":{"answer":"风格一致但换措辞失败，说明可能只复制了采样路径而非完整教师分布。","evidence":"只复制了采样路径"},"boundary":{"answer":"API 不开放 logits、词表不齐或层无法对应，都会限制可用蒸馏方法。","evidence":"强行逐层匹配会限制学生自己的表示方式"}},{"section":5,"definition":{"answer":"学生容量是其参数、层数、上下文、词表和计算深度共同限定的行为上限。","evidence":"学生的参数、层数、上下文、词表和计算深度"},"problem":{"answer":"它解释为何再多教师示范也不能把教师的全部能力无损塞进小学生。","evidence":"为什么不能通过足够多示范全部塞进学生"},"inputOutput":{"answer":"输入是学生容量、蒸馏数据与目标权重，输出是被优先保留和先丢失的能力。","evidence":"优先保留高频、易拟合和目标函数权重高的行为"},"mechanism":{"answer":"有限容量在任务间分配表示，数据频率和损失权重决定优化优先级。","evidence":"因互相冲突的任务产生干扰"},"interpretation":{"answer":"增加样本后收益平台表示容量或目标冲突成为瓶颈，不是教师查询仍不足。","evidence":"增加教师样本会进入收益平台"},"boundary":{"answer":"学生单项基准超过教师可能来自匹配、正则或污染，不能推出全面更强。","evidence":"不等于全面更强"}},{"section":6,"definition":{"answer":"蒸馏课程是按目标切片选择、验证、去重并组织教师样本的覆盖方案。","evidence":"用真实流量、困难样本、高风险和对抗集构造课程"},"problem":{"answer":"它防止最强教师只在狭窄数据上教学，导致学生在语言、长度和工具上偏科。","evidence":"最强教师只在短英文 FAQ 上教学"},"inputOutput":{"answer":"输入是真实流量、困难和高风险提示，输出是带版本、概率与验证结果的课程。","evidence":"保留概率/版本/提示"},"mechanism":{"answer":"教师多样采样后由规则、执行器或人工验证，再去重并控制难度与风格。","evidence":"外部规则、执行器或人工验证"},"interpretation":{"answer":"学生只在课程分布逼近教师，不代表凭空获得课程未覆盖的能力。","evidence":"不会凭空获得长上下文、多语言、工具、拒答和故障恢复"},"boundary":{"answer":"教师查询有成本，主动选学生不确定且教师可能有增益的样本更有效。","evidence":"而不是均匀浪费"}},{"section":7,"definition":{"answer":"蒸馏会连同教师的错误、偏见、拒答倾向和不确定性表达一起迁移。","evidence":"软分布会传递教师偏好"},"problem":{"answer":"它反驳小模型天然更安全，并要求用独立真值识别师生共同盲点。","evidence":"是否也自然更安全"},"inputOutput":{"answer":"输入是教师软分布或示范，输出是可能继承或表面化这些行为的学生。","evidence":"序列示范可能包含幻觉、隐私、偏见或过度拒答"},"mechanism":{"answer":"学生模仿教师概率和序列，容量不足时还可能只学安全措辞而丢失条件判断。","evidence":"只学到表面安全措辞"},"interpretation":{"answer":"师生一致或同源验证高分可能只是共同盲点，不能代替安全真值。","evidence":"不用教师一致率代替安全真值"},"boundary":{"answer":"敏感任务需结合硬标签、独立规则、多教师分歧和人工审查。","evidence":"敏感任务结合硬标签"}},{"section":8,"definition":{"answer":"蒸馏、量化、剪枝和 LoRA 分别改变模型行为容量、位宽、结构和适配增量。","evidence":"在不同维度压缩"},"problem":{"answer":"它防止把四种都称为更小的方法误认为具有相同收益与损失来源。","evidence":"它们各改变了什么"},"inputOutput":{"answer":"输入是原模型与压缩目标，输出分别是学生、低位权重、稀疏结构或适配器。","evidence":"训练更小学生行为"},"mechanism":{"answer":"各方法通过重训行为、舍入数值、删除连接或限制低秩更新来减少不同资源。","evidence":"移除权重/结构"},"interpretation":{"answer":"组合后误差会交互，单项方法的独立评测不能代表最终系统。","evidence":"最终组合必须重新端到端评测"},"boundary":{"answer":"量化会放大脆弱切片，教师若已量化，其分布本身也已发生改变。","evidence":"量化可能加剧学生已脆弱切片"}},{"section":9,"definition":{"answer":"部署验收用质量、容量与系统成本的联合前沿判断压缩是否值得。","evidence":"部署证据是质量—容量—成本前沿"},"problem":{"answer":"它检验学生参数更少是否真正降低每次成功任务成本，而非只让失败更便宜。","evidence":"更便宜但更常失败"},"inputOutput":{"answer":"输入是师生逐样本与系统测量，输出是能力损失切片和成本收益前沿。","evidence":"同时报告逐 token KL/困惑度"},"mechanism":{"answer":"比较目标、长上下文、安全等质量切片及延迟、能耗和人工接管成本。","evidence":"系统侧测 TTFT/TPOT、吞吐、显存、能耗"},"interpretation":{"answer":"teacher-only、student-only 与 both-wrong 切片区分迁移损失和教师自身错误。","evidence":"教师本身错误不能算学生“未模仿失败”"},"boundary":{"answer":"只有硬风险门槛通过、硬件收益真实且牺牲能力可回退时才可接受。","evidence":"硬风险门槛通过"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>手算温度软标签与 KL 目标；区分 logit/特征/序列蒸馏；设计覆盖与教师查询策略；评测能力损失和系统收益。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>硬标签只给答案，软分布还给相对关系<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">同样正确答案是 refund，教师对 ask 仍给 35% 与只给 1% 有何不同？</p><p><b>知识蒸馏</b>用一个较强或较大的教师模型，为较小学生模型产生训练信号。硬标签只给最终正确类别，例如 refund=1、其他=0；软分布则给每个候选的概率。输入是同一条退款案例，教师输出 refund、ask、reject 的整张概率表，学生再学习逼近这张表。</p><p>教师给 ask 35% 表示案例接近“信息不足、应先询问”的边界；只给 1% 则表示证据更明确。硬 one-hot 标签都写 refund，丢掉这种类别相似性和边界信息。学生拟合教师完整分布，可获得更平滑、样本效率更高的监督。</p><p>学生更接近教师只表示行为迁移成功，不表示教师判断是真值。但教师概率可能失准；“更暗的知识”不自动等于真理。硬真值与教师信号应组合，并在真实标签上校准。</p><div class=\"dd-note\"><b>蒸馏对象：</b>可拟合 logits、隐藏表示、注意力、序列示范、偏好或验证反馈；每种可见信息不同。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>温度把次优类别从接近零处拉出来<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">为什么 T>1 能显示教师认为哪些错误“比较像”？</p><div class=\"dd-formula\" data-formula-id=\"distillation-soft-target-loss\" data-display=\"mathml\"><math display=\"block\" aria-label=\"温度 T 下第 i 类概率等于 softmax 对第 i 个 logit 除以 T；总损失等于 alpha 乘硬标签损失，加一减 alpha 乘 T 平方和教师学生软分布的 KL 散度\"><mtable><mtr><mtd><msubsup><mi>p</mi><mi>i</mi><mi>T</mi></msubsup><mo>=</mo><msub><mi>softmax</mi><mi>i</mi></msub><mo>(</mo><mfrac><mi>z</mi><mi>T</mi></mfrac><mo>)</mo></mtd></mtr><mtr><mtd><mi>L</mi><mo>=</mo><mi>α</mi><msub><mi>L</mi><mtext>硬标签</mtext></msub><mo>+</mo><mo>(</mo><mn>1</mn><mo>−</mo><mi>α</mi><mo>)</mo><msup><mi>T</mi><mn>2</mn></msup><mo>·</mo><mi>KL</mi><mo>(</mo><msubsup><mi>p</mi><mtext>教师</mtext><mi>T</mi></msubsup><mo>∥</mo><msubsup><mi>p</mi><mtext>学生</mtext><mi>T</mi></msubsup><mo>)</mo></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>z</code> 是各类别未经归一化的原始分数（logits），<code>i</code> 是类别编号，<code>T</code> 是温度；softmax 把 <code>z/T</code> 变成总和为 1 的概率 <code>pᵀᵢ</code>。<code>L</code> 是学生的总训练损失，<code>L硬标签</code> 衡量学生与人工真值的差距，<code>α</code> 在 0 到 1 之间，控制真值监督与教师监督的比例。<code>KL(p教师∥p学生)</code> 衡量学生软分布偏离教师软分布多少；它不是对称距离，交换两边会改变惩罚重点。</p><p>增大 T 缩小 logit 差，使分布更平；低概率类别产生可学习梯度。乘 T² 常用于补偿 softmax 导数随温度升高而缩小的梯度尺度。训练后推理通常恢复 T=1。</p><p>KL 方向也重要：经典方向对教师赋予非零概率而学生漏掉的类别惩罚更明显，鼓励学生覆盖教师分布；反向 KL 更容易集中于少数高概率模式。生成式模型也可改用序列级目标，因此不能只写“用了 KL”而不说明方向和样本单位。</p><div class=\"dd-note warn\"><b>温度不是校准修复。</b>　它用于训练信号软化，不保证教师或学生的部署概率可信。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>运行示例：三个退款动作的温度软化<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">教师 logits [4,2,0] 在 T=1 与 T=2 时怎样变化？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 250\" role=\"img\" aria-label=\"教师三个动作 logits 经温度一和温度二 softmax 后的概率柱状图\"><rect x=\"30\" y=\"40\" width=\"290\" height=\"170\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"175\" y=\"66\" text-anchor=\"middle\" class=\"svg-t\">T=1：尖锐</text><rect x=\"75\" y=\"88\" width=\"45\" height=\"92\" fill=\"#4f9d78\"/><text x=\"97\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">refund .867</text><rect x=\"160\" y=\"166\" width=\"45\" height=\"14\" fill=\"#d3a05a\"/><text x=\"182\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">ask .117</text><rect x=\"245\" y=\"177\" width=\"45\" height=\"3\" fill=\"#c77b72\"/><text x=\"267\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">reject .016</text><rect x=\"380\" y=\"40\" width=\"290\" height=\"170\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"525\" y=\"66\" text-anchor=\"middle\" class=\"svg-t\">T=2：软化</text><rect x=\"425\" y=\"115\" width=\"45\" height=\"65\" fill=\"#4f9d78\"/><text x=\"447\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">refund .665</text><rect x=\"510\" y=\"156\" width=\"45\" height=\"24\" fill=\"#d3a05a\"/><text x=\"532\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">ask .245</text><rect x=\"595\" y=\"171\" width=\"45\" height=\"9\" fill=\"#c77b72\"/><text x=\"617\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">reject .090</text></svg><figcaption>图 1　温度 2 保持排序，却让 ask/reject 的相对信息更可见。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>动作</th><th>logit</th><th>e^z / Σ（T=1）</th><th>e^(z/2) / Σ（T=2）</th></tr></thead><tbody><tr><td>refund</td><td>4</td><td>.867</td><td>.665</td></tr><tr><td>ask</td><td>2</td><td>.117</td><td>.245</td></tr><tr><td>reject</td><td>0</td><td>.016</td><td>.090</td></tr></tbody></table></div><p>若学生输出 [.60,.30,.10]，T=2 分布能明确奖励它给 ask/reject 留概率；仅硬标签会只推动 refund 接近 1。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>logit、特征与关系蒸馏要求不同接口<span class=\"dd-badge eng\">方法</span></h2><p class=\"dd-lead\">拿不到教师内部状态时，还能蒸馏什么？</p><p>先区分四种信号：<b>logit</b> 是 softmax 前的候选原始分数；<b>特征</b>是教师中间层产生的向量；<b>关系</b>是样本或层之间的相似结构；<b>序列</b>是教师最终生成的一条回答。越靠内部，提供的信息越细，但越要求访问教师模型内部。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>教师信号</th><th>要求</th><th>盲区</th></tr></thead><tbody><tr><td>Logit/token</td><td>每类/词表分布</td><td>可访问 logits、词表对齐</td><td>API 常不开放全量</td></tr><tr><td>Feature</td><td>隐藏层/注意力</td><td>层映射和维度投影</td><td>架构差异大</td></tr><tr><td>Relation</td><td>样本/层间相似关系</td><td>批内对照</td><td>目标间接</td></tr><tr><td>Sequence</td><td>回答/解释/偏好</td><td>只需生成 API</td><td>只见采样路径</td></tr></tbody></table></div><p>选择方法的输入是可用教师接口、学生架构和要保留的能力，输出是概率、特征、关系或示范数据以及相应学生损失。LLM 常用序列蒸馏：教师为多样提示生成示范，再 SFT/偏好训练学生。它更像行为克隆，无法看到教师对未采样 token 的概率，也容易复制教师文风和冗长。</p><p>若学生在示范风格上高度一致却在换措辞后失败，应解释为只复制了采样路径，不是完整迁移教师分布。不同架构还可能没有可直接对应的层，此时强行逐层匹配会限制学生自己的表示方式。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>学生容量与架构决定可保留上限<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">教师能做的事情，为什么不能通过足够多示范全部塞进学生？</p><p>学生的参数、层数、上下文、词表和计算深度限制表示与算法。蒸馏数据会让它优先保留高频、易拟合和目标函数权重高的行为；罕见推理、长上下文、校准、对抗鲁棒和工具恢复可能先丢。</p><p>若学生容量不足，增加教师样本会进入收益平台，甚至因互相冲突的任务产生干扰。应画能力—参数—延迟前沿，不把“教师全能力复刻”作为默认承诺。</p><div class=\"dd-note warn\"><b>学生在某基准超过教师不等于全面更强。</b>　可能来自正则化、数据更匹配或评测污染。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>数据覆盖比教师品牌更决定学生偏科<span class=\"dd-badge eng\">数据</span></h2><p class=\"dd-lead\">最强教师只在短英文 FAQ 上教学，会得到怎样的学生？</p><p>它会在该分布逼近教师，却不会凭空获得长上下文、多语言、工具、拒答和故障恢复。用真实流量、困难样本、高风险和对抗集构造课程；对教师不确定或验证失败样本保留人工真值，不强制模仿。</p><ol class=\"dd-steps\"><li>按目标切片抽真实/合成提示。</li><li>教师多样采样，保留概率/版本/提示。</li><li>外部规则、执行器或人工验证。</li><li>去重并控制难度与教师风格。</li><li>在不含教师近邻的真实集验收。</li></ol><p>教师查询有成本，可主动选择学生最不确定、教师可能有增益的样本，而不是均匀浪费。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>教师错误、偏见和拒答会一并传递<span class=\"dd-badge eng\">风险</span></h2><p class=\"dd-lead\">学生更小、更便宜，是否也自然更安全？</p><p>不会。序列示范可能包含幻觉、隐私、偏见或过度拒答；软分布会传递教师偏好。若教师与验证器同源，高通过率可只是共同盲点。敏感任务结合硬标签、独立规则、多教师分歧和人工审查。</p><p>还要关注反向影响：学生容量不足可能只学到表面安全措辞而失去条件判断，造成对危险请求漏拒或对正常请求全拒。按风险切片比较教师、学生与真实标签，不用教师一致率代替安全真值。</p><div class=\"dd-note warn\"><b>蒸馏可能洗掉不确定性。</b>　单一教师贪心答案让学生看不到多模态分布，表现得比证据更确定。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>蒸馏、量化、剪枝和 LoRA 在不同维度压缩<span class=\"dd-badge eng\">组合</span></h2><p class=\"dd-lead\">四种方法都说“更小”，它们各改变了什么？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方法</th><th>改变</th><th>主要收益</th><th>主要损失源</th></tr></thead><tbody><tr><td>蒸馏</td><td>训练更小学生行为</td><td>参数/FLOPs</td><td>容量与覆盖</td></tr><tr><td>量化</td><td>数值位宽</td><td>存储/带宽</td><td>舍入/截断</td></tr><tr><td>剪枝</td><td>移除权重/结构</td><td>稀疏/算力</td><td>删去重要连接</td></tr><tr><td>LoRA</td><td>低秩任务增量</td><td>训练状态/切换</td><td>适配容量与干扰</td></tr></tbody></table></div><p>可以先蒸馏再量化学生，但误差会交互：量化可能加剧学生已脆弱切片；蒸馏教师若本身量化，分布已改变。最终组合必须重新端到端评测。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>部署证据是质量—容量—成本前沿<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">学生参数少 70%，怎样证明它不是“更便宜但更常失败”？</p><p>同时报告逐 token KL/困惑度、目标任务、长上下文、多语言、工具、安全、校准和分布外切片；系统侧测 TTFT/TPOT、吞吐、显存、能耗、人工接管和每成功任务成本。与同预算强模型路由/量化基线比较。</p><p>逐样本检查 teacher-only-correct、student-only-correct、both-wrong；能力损失集中在哪些切片。教师本身错误不能算学生“未模仿失败”。发布后流量漂移需重新蒸馏或路由升级。</p><div class=\"dd-note\"><b>可接受压缩：</b>硬风险门槛通过，目标硬件收益真实，且被牺牲能力明确、可路由或可回退。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">蒸馏是受容量和数据约束的行为迁移，不是完整知识复制。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>软标签都是真实知识</td><td>它们包含教师关系，也包含失准和偏见</td></tr><tr><td>温度越高越好</td><td>过高会抹平有用差异，需调参与验证</td></tr><tr><td>序列示范等于完整分布</td><td>只观察被采样路径</td></tr><tr><td>示范足够多可复制全部能力</td><td>学生容量和覆盖决定上限</td></tr><tr><td>小模型天然安全</td><td>安全判断也可能蒸馏失败或表面化</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>softmax、KL、监督学习、模型容量</td></tr><tr><td><b>本页核心</b></td><td>温度软标签、logit/feature/sequence 蒸馏、课程覆盖</td></tr><tr><td>数据</td><td>合成数据、训练数据治理、后训练</td></tr><tr><td>压缩部署</td><td>量化、LoRA、模型路由与应用评测</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义学生需保留的能力切片</li><li>教师产生分布/表示/示范</li><li>独立验证并构造覆盖课程</li><li>学生联合拟合硬标签与教师信号</li><li>比较逐样本能力迁移与丢失</li><li>系统收益/风险联合门禁并保留升级</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>T=2 对 [4,2,0] 的概率约多少？</li><li>为什么损失常乘 T²？</li><li>序列蒸馏缺少什么教师信息？</li><li>学生为何会偏科？</li><li>学生超过教师单项分数代表什么？</li><li>假设“知识蒸馏：让小学生逼近教师的条件分布与行为”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“知识蒸馏：让小学生逼近教师的条件分布与行为”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>约 [.665,.245,.090]。</li><li>补偿 softmax 导数/梯度随温度缩小的尺度。</li><li>未采样 token 和其他路径的完整概率分布。</li><li>容量有限且蒸馏数据/目标对某些切片权重更高。</li><li>仅说明该评测上可能更好，不能推断全面能力或安全。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1503.02531\" target=\"_blank\" rel=\"noopener\">Distilling the Knowledge in a Neural Network</a>：温度软标签与经典蒸馏</li><li><a href=\"https://arxiv.org/abs/1910.01108\" target=\"_blank\" rel=\"noopener\">DistilBERT</a>：语言模型多目标蒸馏</li><li><a href=\"https://arxiv.org/abs/2306.08543\" target=\"_blank\" rel=\"noopener\">MiniLLM</a>：生成式语言模型蒸馏目标</li><li><a href=\"https://arxiv.org/abs/1606.07947\" target=\"_blank\" rel=\"noopener\">Sequence-Level Knowledge Distillation</a>：序列级示范蒸馏</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
